// The vertical metrics of SF on iOS (font units of a 2048 em), measured by
// the harness: UIFont's ascender and descender are these at every size and
// weight. macOS's SFNS.ttf, which renders iOS frames here, has 1980 and
// 432, so iOS lines would be 0.27 pt short at 17 pt without them.
export const IOS_SF_METRICS = { ascender: 1950, descender: 494, units: 2048 };

// The default font family per platform when a text names none.
export const DEFAULT_FONTS = { ios: "SF Pro", android: "Roboto", web: "system-ui" };

// How each platform sets a line of text:
// - leading_above: the share of a line's extra height (line height minus
//   the font's ascent + descent) above the text. Compose centres text in
//   its line height (LineHeightStyle.Center, trim none) and CSS splits the
//   half-leading, so both are 0.5. iOS puts it all below the line.
// - last_leading: whether the last line keeps its extra height. SwiftUI
//   and UIKit only put leading between lines: one line of body is the
//   font's 20.29 pt (20.33 on the @3x grid), two lines are 20.29 + 22
//   (measured by the harness); Compose and CSS give every line its height.
// - trak: whether the font's `trak` table applies (Core Text does; Skia on
//   Android and Chrome do not).
// - opsz: whether `opsz` follows the point size (Core Text, CSS
//   font-optical-sizing: auto; Compose leaves the axis at its default).
// - named_weights: whether a weight maps through the font's named
//   instances (Apple: semibold is SF's wght 590) or is the `wght` value
//   (CSS, Compose).
export const LINE_RULES = {
  ios: { leading_above: 0, last_leading: false, trak: true, opsz: true, named_weights: true },
  android: { leading_above: 0.5, last_leading: true, trak: false, opsz: false, named_weights: false },
  web: { leading_above: 0.5, last_leading: true, trak: false, opsz: true, named_weights: false },
};

